#!/usr/bin/env node
/**
 * Native plugin parity gate (audit finding C-2).
 *
 * The iOS (`ios/App/CapApp-SPM/Package.swift`) and Android
 * (`android/app/capacitor.build.gradle`, `android/capacitor.settings.gradle`)
 * project files are generated by `npx cap sync` and checked into the repo.
 * When a Capacitor plugin is added to package.json but the sync is never run,
 * the JS calls the bridge for a plugin the binary does not contain — Google /
 * Apple sign-in, HealthKit and the barcode scanner all fail silently on
 * device while everything looks fine in the browser.
 *
 * This script diffs the installed Capacitor plugins against those generated
 * files and fails when any plugin is missing.
 *
 * Usage: node scripts/check-native-plugin-parity.mjs
 */
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const ROOT = process.cwd();

/**
 * Plugins that intentionally cannot appear in a given platform project.
 * Every entry needs a reason — this is the audit trail reviewers read.
 */
const EXCEPTIONS = {
  ios: {
    "@capacitor-mlkit/barcode-scanning":
      "Ships no Package.swift (CocoaPods only), so it cannot join the SPM app. " +
      "src/lib/barcode-scanner.ts checks BarcodeScanner.isSupported() and falls " +
      "back to the in-webview camera decoder / manual entry on iOS.",
  },
  android: {},
};

function readPackageJson() {
  return JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8"));
}

/** Every dependency that declares a `capacitor` section for the platform. */
function installedPlugins(platform) {
  const pkg = readPackageJson();
  const deps = { ...(pkg.dependencies ?? {}), ...(pkg.devDependencies ?? {}) };
  const found = [];
  for (const name of Object.keys(deps)) {
    if (name === "@capacitor/core" || name === "@capacitor/cli") continue;
    if (name === "@capacitor/ios" || name === "@capacitor/android") continue;
    const manifest = join(ROOT, "node_modules", name, "package.json");
    if (!existsSync(manifest)) continue;
    let json;
    try {
      json = JSON.parse(readFileSync(manifest, "utf8"));
    } catch {
      continue;
    }
    if (json.capacitor && json.capacitor[platform]) found.push(name);
  }
  return found.sort();
}

function fileOrEmpty(relative) {
  const path = join(ROOT, relative);
  return existsSync(path) ? readFileSync(path, "utf8") : "";
}

/** `@capgo/capacitor-health` → `CapgoCapacitorHealth` (Capacitor's SPM naming). */
function spmName(pluginName) {
  return pluginName
    .replace(/^@/, "")
    .split(/[/@-]/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
}

export function checkPlatform(platform) {
  const sources =
    platform === "ios"
      ? [fileOrEmpty("ios/App/CapApp-SPM/Package.swift")]
      : [
          fileOrEmpty("android/app/capacitor.build.gradle"),
          fileOrEmpty("android/capacitor.settings.gradle"),
        ];
  const haystack = sources.join("\n");
  const missing = [];
  const excepted = [];
  for (const plugin of installedPlugins(platform)) {
    const exception = EXCEPTIONS[platform][plugin];
    const registered = haystack.includes(plugin) || haystack.includes(spmName(plugin));
    if (registered) continue;
    if (exception) {
      excepted.push({ plugin, reason: exception });
      continue;
    }
    missing.push(plugin);
  }
  return { missing, excepted };
}

export function checkAll() {
  return { ios: checkPlatform("ios"), android: checkPlatform("android") };
}

const isMain = process.argv[1] && import.meta.url === `file://${process.argv[1]}`;

if (isMain) {
  const result = checkAll();
  let failed = false;
  for (const platform of ["ios", "android"]) {
    const { missing, excepted } = result[platform];
    for (const { plugin, reason } of excepted) {
      console.log(`· ${platform}: ${plugin} intentionally absent — ${reason}`);
    }
    if (missing.length) {
      failed = true;
      console.error(
        `✖ ${platform}: ${missing.length} Capacitor plugin(s) missing from the checked-in native project:`,
      );
      for (const plugin of missing) console.error(`    - ${plugin}`);
    } else {
      console.log(`✔ ${platform}: every installed Capacitor plugin is registered.`);
    }
  }
  if (failed) {
    console.error("\nRun `npm run build && npx cap sync` and commit the generated native files.");
    process.exit(1);
  }
}
